import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.Quf--mN6.js";const u=JSON.parse('{"title":"The Servus Mental Model","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/mental-model.md","filePath":"getting-started/mental-model.md","lastUpdated":1776695999000}'),o={name:"getting-started/mental-model.md"};function i(r,e,c,l,d,h){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="the-servus-mental-model" tabindex="-1">The Servus Mental Model <a class="header-anchor" href="#the-servus-mental-model" aria-label="Permalink to &quot;The Servus Mental Model&quot;">​</a></h1><h2 id="how-to-think-about-services" tabindex="-1">How to think about services <a class="header-anchor" href="#how-to-think-about-services" aria-label="Permalink to &quot;How to think about services&quot;">​</a></h2><p>A Servus service is an internal API for a business action. Controllers, models, jobs, other services, and rake tasks all call it the same way — <code>Service.call(**args)</code> — and get back the same <code>Response</code>. When the work should happen in the background, <code>Service.call_async(**args)</code> enqueues it through ActiveJob without changing the service itself.</p><p>The caller doesn&#39;t need to know how the service works internally. It passes arguments, gets a response, and branches on <code>success?</code> if necessary. That contract holds whether the caller is a controller rendering JSON, a job running in the background, or another service composing a larger workflow.</p><h2 id="the-execution-lifecycle" tabindex="-1">The execution lifecycle <a class="header-anchor" href="#the-execution-lifecycle" aria-label="Permalink to &quot;The execution lifecycle&quot;">​</a></h2><p>When you call <code>Service.call(**args)</code>, your <code>call</code> method isn&#39;t invoked directly. Servus wraps it in a lifecycle that handles validation, timing, error handling, event emission, and logging automatically.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service.call(**args)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├── Log the call and arguments</span></span>
<span class="line"><span>  ├── Validate arguments against schema (if defined)</span></span>
<span class="line"><span>  ├── Instantiate the service</span></span>
<span class="line"><span>  ├── Run your \`call\` method</span></span>
<span class="line"><span>  ├── Validate the result against schema (if defined)</span></span>
<span class="line"><span>  ├── Emit events (if defined)</span></span>
<span class="line"><span>  ├── Log success or failure with duration</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └── Return Response</span></span></code></pre></div><p>Your <code>call</code> method only contains business logic. Everything above and below it is handled by the runtime.</p><h2 id="why-this-matters-in-practice" tabindex="-1">Why this matters in practice <a class="header-anchor" href="#why-this-matters-in-practice" aria-label="Permalink to &quot;Why this matters in practice&quot;">​</a></h2><p><strong>Testability.</strong> When the business logic lives behind <code>Service.call(**args) → Response</code>, you test it by passing arguments and asserting on the response. No controller setup, no job infrastructure, no request context. Inputs in, outputs out.</p><p><strong>Reusability.</strong> A service isn&#39;t tied to a controller action, a callback, or a job. The same service can be called from a web request, a background worker, a rake task, or another service — without changing anything.</p><p><strong>Discoverability.</strong> The service name is the action name. <code>Treasury::TransferGold::Service</code> tells you what it does and where to find it (<code>app/services/treasury/transfer_gold/service.rb</code>). When something breaks, you grep one name and land in one file.</p><h2 id="one-rule-for-reading-services" tabindex="-1">One rule for reading services <a class="header-anchor" href="#one-rule-for-reading-services" aria-label="Permalink to &quot;One rule for reading services&quot;">​</a></h2><p>The <code>call</code> method should contain the business decision. Private methods and <code>Support::</code> classes can support it, but they should not become a second response layer or a second orchestration boundary. If a private method is returning <code>success</code> or <code>failure</code>, it probably belongs in its own service.</p>`,14)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
